import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <mma.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
namespace cute_matmul_detail {
using namespace cute;
using namespace nvcuda;
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int THREADS = 256;
constexpr int WARPS = THREADS / 32;
constexpr int WM = 16;
constexpr int WN = 16;
constexpr int WK = 8;
constexpr int WARP_TILES = (BM / WM) * (BN / WN) / WARPS;
__global__ __launch_bounds__(THREADS)
void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    __shared__ float smem_a[BM * WK];
    __shared__ float smem_b[WK * BN];
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp_id = tid >> 5;
    const int block_row = blockIdx.y * BM;
    const int block_col = blockIdx.x * BN;
    wmma::fragment<wmma::accumulator, WM, WN, WK, float> accum[WARP_TILES];
    #pragma unroll
    for (int t = 0; t < WARP_TILES; ++t) {
        wmma::fill_fragment(accum[t], 0.0f);
    }
    for (int k_tile = 0; k_tile < K; k_tile += WK) {
        for (int linear = tid; linear < BM * WK; linear += THREADS) {
            const int local_row = linear / WK;
            const int local_k = linear % WK;
            const int global_row = block_row + local_row;
            const int global_k = k_tile + local_k;
            smem_a[linear] =
                (global_row < M && global_k < K)
                    ? A[global_row * K + global_k]
                    : 0.0f;
        }
        for (int linear = tid; linear < WK * BN; linear += THREADS) {
            const int local_k = linear / BN;
            const int local_col = linear % BN;
            const int global_k = k_tile + local_k;
            const int global_col = block_col + local_col;
            smem_b[linear] =
                (global_k < K && global_col < N)
                    ? B[global_k * N + global_col]
                    : 0.0f;
        }
        __syncthreads();
        #pragma unroll
        for (int t = 0; t < WARP_TILES; ++t) {
            const int tile_id = warp_id + t * WARPS;
            const int tile_row = tile_id / (BN / WN);
            const int tile_col = tile_id % (BN / WN);
            wmma::fragment<wmma::matrix_a, WM, WN, WK,
                           wmma::precision::tf32, wmma::row_major> a_frag;
            wmma::fragment<wmma::matrix_b, WM, WN, WK,
                           wmma::precision::tf32, wmma::row_major> b_frag;
            const float* a_ptr =
                &smem_a[(tile_row * WM) * WK];
            const float* b_ptr =
                &smem_b[tile_col * WN];
            wmma::load_matrix_sync(a_frag, a_ptr, WK);
            wmma::load_matrix_sync(b_frag, b_ptr, BN);
            wmma::mma_sync(accum[t], a_frag, b_frag, accum[t]);
        }
        __syncthreads();
    }
    #pragma unroll
    for (int t = 0; t < WARP_TILES; ++t) {
        const int tile_id = warp_id + t * WARPS;
        const int tile_row = tile_id / (BN / WN);
        const int tile_col = tile_id % (BN / WN);
        const int global_row = block_row + tile_row * WM;
        const int global_col = block_col + tile_col * WN;
        if (global_row < M && global_col < N) {
            wmma::store_matrix_sync(
                C + global_row * N + global_col,
                accum[t],
                N,
                wmma::mem_row_major);
        }
    }
}
} // namespace cute_matmul_detail
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat &&
                B.scalar_type() == at::kFloat,
                "A and B must be float32 tensors");
    TORCH_CHECK(A.size(1) == B.size(0),
                "A.size(1) must equal B.size(0)");
    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();
    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));
    auto C = torch::empty({M, N}, A_contig.options());
    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::BN - 1) / cute_matmul_detail::BN,
        (M + cute_matmul_detail::BM - 1) / cute_matmul_detail::BM);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matmul_detail::cute_matmul_kernel<<<grid, block, 0, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE matrix multiplication kernel launch failed");
    return C;
}
"""


cute_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

