#include <torch/extension.h>
#include <cuda_runtime.h>
#include <mma.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>


namespace cute_matmul_detail {
using namespace cute;

constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int THREADS = 256;
constexpr int THREAD_ROWS = 16;
constexpr int THREAD_COLS = BN / 32;
constexpr int SMEM_B_STRIDE = BN + 4;

__global__ __launch_bounds__(THREADS)
void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    __shared__ float smem_a[BM * BK];
    __shared__ float smem_b[BK * SMEM_B_STRIDE];

    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));

    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));

    auto sA = make_tensor(
        make_smem_ptr(smem_a),
        make_shape(Int<BM>{}, Int<BK>{}),
        make_stride(Int<BK>{}, Int<1>{}));

    auto sB = make_tensor(
        make_smem_ptr(smem_b),
        make_shape(Int<BK>{}, Int<BN>{}),
         make_stride(Int<SMEM_B_STRIDE>{}, Int<1>{}));

    const int tid = threadIdx.x;
    const int block_row = blockIdx.y * BM;
    const int block_col = blockIdx.x * BN;

    const int thread_group = tid / 32;
    const int lane = tid % 32;

    const int row_base = thread_group * THREAD_ROWS;
    const int col_base = lane;

    float accum[THREAD_ROWS][THREAD_COLS];

    #pragma unroll
    for (int i = 0; i < THREAD_ROWS; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_COLS; ++j) {
            accum[i][j] = 0.0f;
        }
    }

    const bool use_vectorized_loads =
        (M % BM == 0) && (N % BN == 0) &&
        (K % BK == 0) && (K % 4 == 0) && (N % 4 == 0);
    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        if (use_vectorized_loads) {
            for (int linear = tid; linear < (BM * BK) / 4; linear += THREADS) {
                const int element = linear * 4;
                const int local_row = element / BK;
                const int local_k = element % BK;
                const int global_row = block_row + local_row;
                const int global_k = k_tile + local_k;
                reinterpret_cast<float4*>(smem_a)[linear] =
                    reinterpret_cast<const float4*>(A + global_row * K + global_k)[0];
            }
            for (int linear = tid; linear < (BK * BN) / 4; linear += THREADS) {
                const int element = linear * 4;
                const int local_k = element / BN;
                const int local_col = element % BN;
                const int global_k = k_tile + local_k;
                const int global_col = block_col + local_col;
                reinterpret_cast<float4*>(&smem_b[local_k * SMEM_B_STRIDE + local_col])[0] =
                    reinterpret_cast<const float4*>(B + global_k * N + global_col)[0];
            }
        } else {
            for (int linear = tid; linear < BM * BK; linear += THREADS) {
                const int local_row = linear / BK;
                const int local_k = linear % BK;
                const int global_row = block_row + local_row;
                const int global_k = k_tile + local_k;
                sA(local_row, local_k) =
                    (global_row < M && global_k < K)
                        ? gA(global_row, global_k)
                        : 0.0f;
            }
            for (int linear = tid; linear < BK * BN; linear += THREADS) {
                const int local_k = linear / BN;
                const int local_col = linear % BN;
                const int global_k = k_tile + local_k;
                const int global_col = block_col + local_col;
                sB(local_k, local_col) =
                    (global_k < K && global_col < N)
                        ? gB(global_k, global_col)
                        : 0.0f;
            }
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_frag[THREAD_ROWS];
            float b_frag[THREAD_COLS];

            #pragma unroll
            for (int i = 0; i < THREAD_ROWS; ++i) {
                a_frag[i] = sA(row_base + i, kk);
            }

            #pragma unroll
            for (int j = 0; j < THREAD_COLS; ++j) {
                 b_frag[j] = sB(kk, col_base + j * 32);
            }

            #pragma unroll
            for (int i = 0; i < THREAD_ROWS; ++i) {
                #pragma unroll
                for (int j = 0; j < THREAD_COLS; ++j) {
                    accum[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < THREAD_ROWS; ++i) {
        const int global_row = block_row + row_base + i;
        if (global_row < M) {
            #pragma unroll
            for (int j = 0; j < THREAD_COLS; ++j) {
                 const int global_col = block_col + col_base + j * 32;
                if (global_col < N) {
                    gC(global_row, global_col) = accum[i][j];
                }
            }
        }
    }
}

constexpr int OPT_BM = 128;
constexpr int OPT_BN = 128;
constexpr int OPT_BK = 16;
constexpr int OPT_STAGES = 2;
__device__ __forceinline__ void cute_cp_async_16(
    float* dst,
    const float* src)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile(
        "cp.async.ca.shared.global [%0], [%1], 16;"
        ::
        "r"(static_cast<unsigned>(__cvta_generic_to_shared(dst))),
        "l"(src));
#else
    *dst = *src;
#endif
}
__device__ __forceinline__ void cute_cp_async_commit()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;");
#endif
}
__device__ __forceinline__ void cute_cp_async_wait()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.wait_group 0;");
#endif
}
__global__ __launch_bounds__(THREADS)
void cute_matmul_kernel_async(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    __shared__ float smem_a[OPT_STAGES][OPT_BM * OPT_BK];
    __shared__ float smem_b[OPT_STAGES][OPT_BK * OPT_BN];
    auto gA = make_tensor(
        make_gmem_ptr(A),
        make_shape(M, K),
        make_stride(K, Int<1>{}));
    auto gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K, N),
        make_stride(N, Int<1>{}));
    auto gC = make_tensor(
        make_gmem_ptr(C),
        make_shape(M, N),
        make_stride(N, Int<1>{}));
    const int tid = threadIdx.x;
    const int block_row = blockIdx.y * OPT_BM;
    const int block_col = blockIdx.x * OPT_BN;
    const int thread_group = tid / 32;
    const int lane = tid % 32;
    const int row_base = thread_group * 16;
    const int col_base = lane;
    constexpr int THREAD_ROWS_OPT = 16;
    constexpr int THREAD_COLS_OPT = OPT_BN / 32;
    float accum[THREAD_ROWS_OPT][THREAD_COLS_OPT];
    #pragma unroll
    for (int i = 0; i < THREAD_ROWS_OPT; ++i) {
        #pragma unroll
        for (int j = 0; j < THREAD_COLS_OPT; ++j) {
            accum[i][j] = 0.0f;
        }
    }
    auto load_tile = [&](int stage, int k_tile) {
        for (int linear = tid; linear < (OPT_BM * OPT_BK) / 4; linear += THREADS) {
            const int element = linear * 4;
            const int local_row = element / OPT_BK;
            const int local_k = element % OPT_BK;
            const int global_row = block_row + local_row;
            const int global_k = k_tile + local_k;
            cute_cp_async_16(
                &smem_a[stage][element],
                A + global_row * K + global_k);
        }
        for (int linear = tid; linear < (OPT_BK * OPT_BN) / 4; linear += THREADS) {
            const int element = linear * 4;
            const int local_k = element / OPT_BN;
            const int local_col = element % OPT_BN;
            const int global_k = k_tile + local_k;
            const int global_col = block_col + local_col;
            cute_cp_async_16(
                &smem_b[stage][element],
                B + global_k * N + global_col);
        }
        cute_cp_async_commit();
    };
    load_tile(0, 0);
    cute_cp_async_wait();
    __syncthreads();
    for (int k_tile = 0, stage = 0; k_tile < K; k_tile += OPT_BK, stage ^= 1) {
        auto sA = make_tensor(
            make_smem_ptr(smem_a[stage]),
            make_shape(Int<OPT_BM>{}, Int<OPT_BK>{}),
            make_stride(Int<OPT_BK>{}, Int<1>{}));
        auto sB = make_tensor(
            make_smem_ptr(smem_b[stage]),
            make_shape(Int<OPT_BK>{}, Int<OPT_BN>{}),
            make_stride(Int<OPT_BN>{}, Int<1>{}));
        if (k_tile + OPT_BK < K) {
            load_tile(stage ^ 1, k_tile + OPT_BK);
        }
        #pragma unroll
        for (int kk = 0; kk < OPT_BK; ++kk) {
            float a_frag[THREAD_ROWS_OPT];
            float b_frag[THREAD_COLS_OPT];
            #pragma unroll
            for (int i = 0; i < THREAD_ROWS_OPT; ++i) {
                a_frag[i] = sA(row_base + i, kk);
            }
            #pragma unroll
            for (int j = 0; j < THREAD_COLS_OPT; ++j) {
                b_frag[j] = sB(kk, col_base + j * 32);
            }
            #pragma unroll
            for (int i = 0; i < THREAD_ROWS_OPT; ++i) {
                #pragma unroll
                for (int j = 0; j < THREAD_COLS_OPT; ++j) {
                    accum[i][j] += a_frag[i] * b_frag[j];
                }
            }
        }
        if (k_tile + OPT_BK < K) {
            cute_cp_async_wait();
            __syncthreads();
        }
    }
    #pragma unroll
    for (int i = 0; i < THREAD_ROWS_OPT; ++i) {
        const int global_row = block_row + row_base + i;
        if (global_row < M) {
            #pragma unroll
            for (int j = 0; j < THREAD_COLS_OPT; ++j) {
                const int global_col = block_col + col_base + j * 32;
                if (global_col < N) {
                    gC(global_row, global_col) = accum[i][j];
                }
            }
        }
    }
}

} // namespace cute_matmul_detail
