#endif
}
__global__ __launch_bounds__(THREADS)
void cute_matmul_kernel_async(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int N,
    int K)
{
    __shared__ __align__(16) float smem_a[OPT_BM * OPT_BK];
    __shared__ __align__(16) float smem_b[OPT_BK * OPT_BN];
    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int block_row = blockIdx.y * OPT_BM;
    const int block_col = blockIdx.x * OPT_BN;
    using namespace nvcuda;
    namespace wmma = nvcuda::wmma;
    wmma::fragment<wmma::accumulator, 16, 16, 8, float>
        acc[2][2];
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
            wmma::fill_fragment(acc[i][j], 0.0f);
        }
    }
    const int row_pair = warp_id % 4;
    const int col_pair = warp_id / 4;
    for (int k_tile = 0; k_tile < K; k_tile += OPT_BK) {
        for (int linear = tid; linear < (OPT_BM * OPT_BK) / 4; linear += THREADS) {
            const int element = linear * 4;
            const int local_row = element / OPT_BK;
            const int local_k = element % OPT_BK;
            const int global_row = block_row + local_row;
            const int global_k = k_tile + local_k;
            reinterpret_cast<float4*>(smem_a)[linear] =
                reinterpret_cast<const float4*>(A + global_row * K + global_k)[0];
        }
        for (int linear = tid; linear < (OPT_BK * OPT_BN) / 4; linear += THREADS) {
            const int element = linear * 4;
            const int local_k = element / OPT_BN;
            const int local_col = element % OPT_BN;
            const int global_k = k_tile + local_k;
            const int global_col = block_col + local_col;
            reinterpret_cast<float4*>(smem_b)[linear] =
                reinterpret_cast<const float4*>(B + global_k * N + global_col)[0];
        }
        __syncthreads();
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            #pragma unroll
            for (int c = 0; c < 2; ++c) {
                const int tile_row = (row_pair * 2 + r) * 16;
                const int tile_col = (col_pair * 2 + c) * 16;
                #pragma unroll
                for (int kk = 0; kk < OPT_BK; kk += 8) {
                    wmma::fragment<
                        wmma::matrix_a,
                        16, 16, 8,
                        wmma::precision::tf32,
                        wmma::row_major> a_frag;
                    wmma::fragment<
                        wmma::matrix_b,
                        16, 16, 8,
                        wmma::precision::tf32,
                        wmma::row_major> b_frag;
                    wmma::load_matrix_sync(
                        a_frag,
                        smem_a + tile_row * OPT_BK + kk,
                        OPT_BK);
                    wmma::load_matrix_sync(
                        b_frag,
                        smem_b + kk * OPT_BN + tile_col,
                        OPT_BN);
                    wmma::mma_sync(
                        acc[r][c],
                        a_frag,
                        b_frag,
                        acc[r][c]);
                }
        }
        } // r
        __syncthreads();
    }
    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        #pragma unroll
        for (int c = 0; c < 2; ++c) {
            const int tile_row = block_row + (row_pair * 2 + r) * 16;
            const int tile_col = block_col + (col_pair * 2 + c) * 16;
            wmma::store_matrix_sync(
                C + tile_row * N + tile_col,
                acc[r][c],
                N,
                wmma::mem_row_major);
        }
    }
}

