torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.scalar_type() == at::kFloat &&
                B.scalar_type() == at::kFloat,
                "A and B must be float32 tensors");
    TORCH_CHECK(A.size(1) == B.size(0),
                "A.size(1) must equal B.size(0)");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    dim3 block(cute_matmul_detail::THREADS);
    dim3 grid(
        (N + cute_matmul_detail::BN - 1) / cute_matmul_detail::BN,
        (M + cute_matmul_detail::BM - 1) / cute_matmul_detail::BM);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if ((M % cute_matmul_detail::OPT_BM == 0) &&
        (N % cute_matmul_detail::OPT_BN == 0) &&
        (K % 16 == 0) &&
        ((reinterpret_cast<uintptr_t>(A_contig.data_ptr<float>()) & 15) == 0) &&
        ((reinterpret_cast<uintptr_t>(B_contig.data_ptr<float>()) & 15) == 0)) {
        cute_matmul_detail::cute_matmul_kernel_async<<<grid, block, 0, stream>>>(
            A_contig.data_ptr<float>(),
            B_contig.data_ptr<float>(),
            C.data_ptr<float>(),
            M,
            N,
            K);
    } else {
        cute_matmul_detail::cute_matmul_kernel<<<grid, block, 0, stream>>>(
            A_contig.data_ptr<float>(),
            B_contig.data_ptr<float>(),
            C.data_ptr<float>(),
            M,
            N,
            K);
    }

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE matrix multiplication kernel launch failed");

    return C;
}
