                        a_frag,
                        smem_a + tile_row * OPT_BK + kk,
                        OPT_BK);
                    wmma::load_matrix_sync(
                        b_frag,
                         smem_b + tile_col * OPT_BK + kk,
                        OPT_BN);
                    wmma::mma_sync(
                        acc[r][c],
                        a_frag,
                        b_frag,
                        acc[r][c]);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        #pragma unroll
        for (int c = 0; c < 4; ++c) {
            const int tile_row = block_row + (row_pair * 2 + r) * 16;
            const int tile_col = (col_pair * 4 + c) * 16;
            wmma::store_matrix_sync(
                C + tile_row * N + tile_col,
                acc[r][c],
                N,
                wmma::mem_row_major);
        }
    }
